This is the configuration file.

```json
{
  "manifest_version": 3,
  "name": "Local Screenshot Saver",
  "version": "1.0",
  "description": "Takes a screenshot of the current page and saves it to your downloads folder.",
  "permissions": [
    "downloads"
  ],
  "action": {
    "default_popup": "popup.html",
    "default_icon": "icon.png"
  },
  "content_scripts": [
    {
      "matches": ["<all_urls>"],
      "js": ["content.js"]
