});

// 1. Backend Filtering Function
// This function takes a query string and returns matching hotels
async function searchHotels(query) {
  if (!query || query.length < 2) return [];

  // Use ILIKE for case-insensitive search
  // We use a parameterized query to prevent SQL injection
  const sql = `
    SELECT id, name, city, country, rating 
    FROM hotels 
    WHERE name ILIKE $1 
    OR city ILIKE $1 
    OR country ILIKE $1
    ORDER BY name ASC
    LIMIT 10
  `;

  const values = `%${query}%`;

  const result = await pool.query(sql, [values]);
  return result.rows;
}

// 2. API Endpoint
