    console.log(`Logged in as ${client.user.tag}`);
    // The client now maintains a persistent WebSocket connection
    // and begins listening for 'message', 'typing', 'voiceStateUpdate', etc.
});

// Event Listener: Message
client.on('messageCreate', async (message) => {
