```kotlin
class CouchbaseService {
    private lateinit var bucketName: String

    private lateinit var cluster: Cluster
    private lateinit var bucket: Bucket

    val logger: Logger = LoggerFactory.getLogger("wisk")

    fun init(couchbaseSettings: WiskCouchbaseSettings) {
        println("Connecting to Couchbase")

        val env = ClusterEnvironment.builder()
            .timeoutConfig(
                TimeoutConfig
                    .kvTimeout(Duration.ofMillis(10000))
            )
            .build()

        this.bucketName = couchbaseSettings.bucketName
        cluster = Cluster.connect(
            couchbaseSettings.serverHost,
            ClusterOptions.clusterOptions(
                PasswordAuthenticator.create(
                    couchbaseSettings.serverUsername,
                    couchbaseSettings.serverPassword
                )
            ).environment(env)
        )
        println("Connected to Couchbase")

        createBucketIfNotExists(couchbaseSettings)

        bucket = cluster.bucket(bucketName)
        bucket.waitUntilReady(Duration.ofSeconds(10))

        createIndexes()

        // Run migrations in a background thread
        runMigrationsInBackground()
    }

    private fun runMigrationsInBackground() {
        // Create a new thread to run the migration logic
        Thread {
            try {
                val runner = MigrationRunner()
                // Pass the cluster to the runner
                runner.runMigrations(cluster)
            } catch (e: Exception) {
                // Log the error so you can debug it later
                logger.error("Error running migrations", e)
            }
        }.start()
    }
}
